create table customers(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, email text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table methods(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, revision text not null, unit text not null, lower_limit numeric, upper_limit numeric, validation_ref text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(lower_limit is null or upper_limit is null or lower_limit<=upper_limit));
create table equipment(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, calibrated_on date, calibration_due date, certificate_ref text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(calibrated_on is null or calibration_due>=calibrated_on));
create table samples(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, customer_id uuid references customers(id) not null, matrix text not null, collected_at timestamptz, received_at timestamptz not null, due_date date not null, condition text not null, location text not null, source text not null default 'local', source_record jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(collected_at is null or collected_at<=received_at));
create table tests(id uuid primary key default gen_random_uuid(), code text unique not null, sample_id uuid references samples(id) not null, method_id uuid references methods(id) not null, equipment_id uuid references equipment(id) not null, analyst text not null, due_date date not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table results(id uuid primary key default gen_random_uuid(), test_id uuid references tests(id) not null, revision integer not null check(revision>0), value numeric not null, uncertainty numeric not null check(uncertainty>=0), measured_at timestamptz not null, analyst text not null, raw_ref text not null, qc text not null check(qc in ('pass','fail','pending')), reason text not null, method_snapshot jsonb not null, equipment_snapshot jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(test_id,revision));
create table reviews(id uuid primary key default gen_random_uuid(), result_id uuid unique references results(id) not null, reviewer text not null, note text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table custody(id uuid primary key default gen_random_uuid(), sample_id uuid references samples(id) not null, happened_at timestamptz not null, handler text not null, location text not null, note text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table issues(id uuid primary key default gen_random_uuid(), code text unique not null, sample_id uuid references samples(id) not null, description text not null, owner text not null, due_date date not null, resolution text, closed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create function touch_updated() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['customers','methods','equipment','samples','tests','issues'] loop execute format('create trigger touch before update on %I for each row execute function touch_updated()',t); end loop; end $$;
create function immutable_record() returns trigger language plpgsql as $$ begin raise exception 'Evidence records are append-only; add a revision'; end $$;
do $$ declare t text; begin foreach t in array array['results','reviews','custody'] loop execute format('create trigger immutable before update or delete on %I for each row execute function immutable_record()',t); end loop; end $$;
create view worklist as
select t.id,t.code,s.code sample,c.name customer,m.code method,t.analyst,t.due_date,e.code equipment,
r.id result_id,r.revision,r.value,r.uncertainty,coalesce(r.method_snapshot->>'unit',m.unit) unit,r.qc,
case when r.id is null then 'awaiting result' when v.id is null then 'awaiting review' else 'reviewed' end status,
case when r.id is null then 'unknown' when (r.method_snapshot->>'lower_limit') is null and (r.method_snapshot->>'upper_limit') is null then 'no limits recorded' when r.value< (r.method_snapshot->>'lower_limit')::numeric or r.value> (r.method_snapshot->>'upper_limit')::numeric then 'outside limits' else 'within recorded limits' end specification,
v.reviewer,r.measured_at
from tests t join samples s on s.id=t.sample_id join customers c on c.id=s.customer_id join methods m on m.id=t.method_id join equipment e on e.id=t.equipment_id
left join lateral (select * from results where test_id=t.id order by revision desc limit 1) r on true
left join reviews v on v.result_id=r.id;
create view attention as
select 'TEST_OVERDUE' rule,code reference,customer,analyst owner,due_date,'Test past due: '||status detail from worklist where due_date<current_date and status<>'reviewed'
union all select 'QC_HOLD',code,customer,analyst,due_date,'Quality control: '||qc from worklist where qc<>'pass'
union all select 'SPECIFICATION',code,customer,analyst,due_date,'Result outside recorded limits' from worklist where specification='outside limits'
union all select 'CALIBRATION',e.code,'Laboratory','Lab manager',e.calibration_due,'Calibration expired or evidence incomplete' from equipment e where e.calibration_due<current_date or e.calibration_due is null or e.calibrated_on is null or nullif(e.certificate_ref,'') is null
union all select 'OPEN_ISSUE',i.code,c.name,i.owner,i.due_date,i.description from issues i join samples s on s.id=i.sample_id join customers c on c.id=s.customer_id where i.closed_at is null
union all select 'SAMPLE_NO_TEST',s.code,c.name,'Intake',s.due_date,'No test assigned' from samples s join customers c on c.id=s.customer_id where not exists(select 1 from tests t where t.sample_id=s.id);
create view turnaround as select customer,count(*) tests,count(*) filter(where status='reviewed') reviewed,count(*) filter(where due_date<current_date and status<>'reviewed') overdue,count(*) filter(where qc='fail') qc_failures,count(*) filter(where specification='outside limits') outside_limits from worklist group by customer;
create index tests_sample on tests(sample_id);
create index custody_sample on custody(sample_id);
